  --subtle: #8a94a6;
  --primary: #4f46e5;
  --primary-dark: #3730a3;
  --primary-soft: #eef2ff;
  --green: #0f9f6e;
  --green-soft: #e8f8f1;
  --amber: #b7791f;
  --amber-soft: #fff7e6;
  --red: #d92d20;
  --red-soft: #fff1f0;
