.flow-no {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--surface-soft);
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.flow-step.done .flow-no {
  background: var(--green-soft);
  color: var(--green);
}

.flow-step.current .flow-no {
  background: var(--primary);
  color: #fff;
}

.flow-step strong {
  display: block;
  font-size: 14px;
}

.flow-step span {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}

.actions-stack {
  display: grid;
  gap: 10px;
}

.notice {
  padding: 12px;
  border-radius: 8px;
  background: var(--amber-soft);
  color: var(--amber);
  font-size: 13px;
  line-height: 1.6;
}

.notice.red {
  background: var(--red-soft);
  color: var(--red);
}

.modal-mask {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(15, 23, 42, 0.36);
}

.modal-mask.show {
  display: flex;
}

.modal {
  width: min(560px, 100%);
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 30px 80px rgba(15, 23, 42, 0.24);
}

.modal-head,
.modal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  border-bottom: 1px solid var(--line);
}

.modal-foot {
  justify-content: flex-end;
  border-top: 1px solid var(--line);
  border-bottom: 0;
}

.modal-head h3 {
  margin: 0;
  font-size: 18px;
}

.modal-body {
  display: grid;
  gap: 12px;
  padding: 18px;
}

.field {
  display: grid;
  gap: 6px;
}

.field label {
  color: #344054;
  font-size: 13px;
  font-weight: 800;
}

.field input,
.field textarea,
.field select {
  width: 100%;
  min-height: 38px;
  padding: 9px 10px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: #fff;
}

.field textarea {
  min-height: 92px;
  resize: vertical;
}

.toast {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 80;
  display: none;
  padding: 12px 14px;
  border-radius: 8px;
  background: #101828;
  color: #fff;
  font-size: 13px;
  box-shadow: 0 18px 50px rgba(15, 23, 42, 0.22);
}

.toast.show {
  display: block;
}

@media (max-width: 1100px) {
  .agent-grid,
  .kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .dashboard-grid,
  .detail-layout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: static;
    height: auto;
  }

  .sidebar-note {
    position: static;
    margin-top: 18px;
  }

  .main {
    padding: 20px 16px 34px;
  }

  .topline,
  .page-head,
  .toolbar,
  .row-between,
  .card-foot {
    align-items: stretch;
    flex-direction: column;
  }

  .search,
  .agent-grid,
  .kpi-grid,
  .info-grid {
    width: 100%;
    grid-template-columns: 1fr;
  }
}

